import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { authService } from '../services/api';

// ─── Logo SVG inline ────────────────────────────────────────────────────────
const GestionyticsLogo = ({ size = 40 }) => (
  <svg width={size} height={size} viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg">
    <rect width="40" height="40" rx="10" fill="#F5A623"/>
    <rect x="8" y="22" width="6" height="10" rx="2" fill="#0F2B46"/>
    <rect x="17" y="16" width="6" height="16" rx="2" fill="#0F2B46"/>
    <rect x="26" y="10" width="6" height="22" rx="2" fill="#0F2B46"/>
    <circle cx="11" cy="18" r="2.5" fill="#0F2B46"/>
    <circle cx="20" cy="12" r="2.5" fill="#0F2B46"/>
    <circle cx="29" cy="6" r="2.5" fill="#0F2B46"/>
    <polyline points="11,18 20,12 29,6" stroke="#0F2B46" strokeWidth="1.5" strokeLinecap="round"/>
  </svg>
);

const Login = () => {
  const [formData, setFormData] = useState({ correoElectronico: '', password: '' });
  const [error, setError]   = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleChange = e =>
    setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = async e => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const response = await authService.login(formData.correoElectronico, formData.password);
      if (response.user.tipo === 'funcionario') navigate('/funcionario');
      else navigate('/dashboard');
    } catch (err) {
      setError(err.message || 'Credenciales inválidas. Intente de nuevo.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={s.root}>
      {/* Panel izquierdo — decorativo */}
      <div style={s.panel}>
        <div style={s.panelInner}>
          <div style={s.brandRow}>
            <GestionyticsLogo size={48} />
            <span style={s.brandName}>Gestionytics</span>
          </div>
          <p style={s.panelTagline}>
            Gestión inteligente de ofertas de formación para el SENA.
          </p>
          <div style={s.panelStats}>
            {[['Ofertas', 'Administradas'], ['Inscritos', 'Registrados'], ['Instructores', 'Activos']].map(([a, b]) => (
              <div key={a} style={s.statCard}>
                <span style={s.statLabel}>{a}</span>
                <span style={s.statSub}>{b}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Panel derecho — formulario */}
      <div style={s.formSide}>
        <div style={s.formCard}>
          <div style={s.mobileLogoRow}>
            <GestionyticsLogo size={36} />
            <span style={s.mobileBrandName}>Gestionytics</span>
          </div>

          <h1 style={s.heading}>Bienvenido de nuevo</h1>
          <p style={s.subheading}>Ingresa con tu cuenta para continuar</p>

          {error && <div style={s.errorBox}>{error}</div>}

          <form onSubmit={handleSubmit} style={s.form}>
            <div style={s.field}>
              <label style={s.label}>Correo electrónico</label>
              <input
                type="email"
                name="correoElectronico"
                value={formData.correoElectronico}
                onChange={handleChange}
                required
                style={s.input}
                placeholder="usuario@sena.edu.co"
                autoComplete="email"
              />
            </div>

            <div style={s.field}>
              <div style={s.labelRow}>
                <label style={s.label}>Contraseña</label>
                <Link to="/recuperar-password" style={s.forgotLink}>
                  ¿Olvidaste tu contraseña?
                </Link>
              </div>
              <input
                type="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                required
                style={s.input}
                placeholder="••••••••"
                autoComplete="current-password"
              />
            </div>

            <button
              type="submit"
              disabled={loading}
              style={loading ? { ...s.btn, ...s.btnDisabled } : s.btn}
            >
              {loading ? 'Verificando...' : 'Iniciar sesión'}
            </button>
          </form>

          <p style={s.registerHint}>
            ¿No tienes cuenta?{' '}
            <Link to="/registro" style={s.registerLink}>Regístrate aquí</Link>
          </p>
        </div>
      </div>
    </div>
  );
};

const s = {
  root: {
    display: 'flex',
    minHeight: '100vh',
    fontFamily: "'Inter', -apple-system, sans-serif",
  },
  // ── Panel izquierdo
  panel: {
    flex: '0 0 440px',
    background: 'linear-gradient(160deg, #0F2B46 0%, #1A3A5C 60%, #16324F 100%)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '48px',
    '@media(max-width:768px)': { display: 'none' },
  },
  panelInner: {
    maxWidth: '320px',
  },
  brandRow: {
    display: 'flex',
    alignItems: 'center',
    gap: '14px',
    marginBottom: '32px',
  },
  brandName: {
    color: '#FFFFFF',
    fontSize: '26px',
    fontWeight: '700',
    letterSpacing: '-0.5px',
  },
  panelTagline: {
    color: '#A0B4C8',
    fontSize: '16px',
    lineHeight: '1.6',
    marginBottom: '48px',
  },
  panelStats: {
    display: 'flex',
    flexDirection: 'column',
    gap: '12px',
  },
  statCard: {
    background: 'rgba(255,255,255,0.07)',
    border: '1px solid rgba(255,255,255,0.10)',
    borderRadius: '10px',
    padding: '16px 20px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  statLabel: {
    color: '#F5A623',
    fontWeight: '600',
    fontSize: '15px',
  },
  statSub: {
    color: '#A0B4C8',
    fontSize: '13px',
  },
  // ── Formulario
  formSide: {
    flex: 1,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: '#F7F8FA',
    padding: '32px 24px',
  },
  formCard: {
    background: '#FFFFFF',
    borderRadius: '16px',
    boxShadow: '0 4px 24px rgba(0,0,0,0.08)',
    padding: '48px 40px',
    width: '100%',
    maxWidth: '420px',
  },
  mobileLogoRow: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    marginBottom: '28px',
    // Solo se muestra en mobile (hacemos el workaround con display flex siempre
    // porque inline-styles no soportan media queries; en producción usar CSS)
  },
  mobileBrandName: {
    fontSize: '20px',
    fontWeight: '700',
    color: '#0F2B46',
  },
  heading: {
    fontSize: '24px',
